const response = $input.first().json;
const tenants = response.tenants || response || [];
const active = Array.isArray(tenants) ? tenants.filter(t => t.status === 'active' || t.status === 'active_production') : [];

const dispatchList = [];
for (const t of active) {
  const crm = String(t.crm_type || 'bitrix24').toLowerCase();
  if (crm === 'both' || crm === 'hybrid' || crm === 'all') {
    dispatchList.push({ json: { ...t, target_crm: 'bitrix24' } });
    dispatchList.push({ json: { ...t, target_crm: 'amocrm' } });
  } else {
    dispatchList.push({ json: { ...t, target_crm: crm } });
  }
}

return dispatchList;
